input.newString:
func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestAddLargeValues(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{
			name: "large positive values",
			a:    1_000_000_000,
			b:    1_000_000_000,
			want: 2_000_000_000,
		},
		{
			name: "maximum int and zero",
			a:    math.MaxInt,
			b:    0,
			want: math.MaxInt,
		},
		{
			name: "half maximum values",
			a:    math.MaxInt / 2,
			b:    math.MaxInt / 2,
			want: math.MaxInt - 1,
		},
		{
			name: "large negative values",
			a:    -1_000_000_000,
			b:    -1_000_000_000,
			want: -2_000_000_000,
		},
		{
			name: "minimum int and zero",
			a:    math.MinInt,
			b:    0,
			want: math.MinInt,
		},
		{
			name: "half minimum values",
			a:    math.MinInt / 2,
			b:    math.MinInt / 2,
			want: math.MinInt,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.a, tt.b); got != tt.want {
				t.Errorf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

